#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

const int NN = 202;
const int INF = 0x3f3f3f3f;

int flow[NN][NN], cap[NN][NN], pre[NN], que[NN], d[NN];

int edmondsKarp(int n, int source, int sink) {
    int p, q, t, i, j;
    while (true) {
        memset(pre, -1, sizeof(pre));
        d[source] = INF;
        p = q = 0;
        que[q++] = source;
        while (p < q && pre[sink] < 0) {
            t = que[p++];
            for (i = 0; i < n; ++i) {
                if (pre[i] < 0 && (j = cap[t][i] - flow[t][i]) > 0) {
                    pre[que[q++] = i] = t;
                    d[i] = min(d[t], j);
                }
            }
        }
        if (pre[sink] < 0) break;
        for (i = sink; i != source; i = pre[i]) {
            flow[pre[i]][i] += d[sink];
            flow[i][pre[i]] -= d[sink];
        }
    }
    int total = 0;
    for (i = 0; i < n; ++i) total += flow[source][i];
    return total;
}

char gridA[11][11], gridB[11][11];
int zombieRow, zombieCol, dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
int distMatrix[101][101];
int N, T;
vector<int> sourceRows, sourceCols;

void bfs(int startR, int startC, int* distances, bool isSourceCheck) {
    queue<pair<int,int>> q;
    distances[startR*N + startC] = 0;
    q.push({startR, startC});
    while (!q.empty()) {
        auto curr = q.front(); q.pop();
        int r = curr.first, c = curr.second;
        int idx = r*N + c;
        int curDist = distances[idx];
        if (isSourceCheck && (distMatrix[zombieRow*N + zombieCol][idx] <= curDist || T <= curDist)) {
            if (distMatrix[zombieRow*N + zombieCol][idx] < curDist || T < curDist) distances[idx] = INF+1;
            continue;
        }
        for (int k = 0; k < 4; ++k) {
            int nr = r + dirs[k][0];
            int nc = c + dirs[k][1];
            if (nr < 0 || nc < 0 || nr == N || nc == N) continue;
            if (gridB[nr][nc] < '0' || gridB[nr][nc] > '9') continue;
            int nidx = nr*N + nc;
            if (distances[nidx] != INF) continue;
            distances[nidx] = curDist + 1;
            q.push({nr, nc});
        }
    }
}

void constructGraph() {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (gridB[i][j] <= '0' || gridB[i][j] > '9') continue;
            sourceRows.push_back(i);
            sourceCols.push_back(j);
            int idx = i*N + j;
            cap[idx + 2 + N*N][1] = gridB[i][j] - '0';
        }
    }
    int zIdx = zombieRow*N + zombieCol;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (gridA[i][j] <= '0' || gridA[i][j] > '9') continue;
            int idx = i*N + j;
            cap[0][idx + 2] = gridA[i][j] - '0';
            for (int k = 0; k < sourceRows.size(); ++k) {
                int ri = sourceRows[k];
                int ci = sourceCols[k];
                int qIdx = ri*N + ci;
                if (distMatrix[idx][qIdx] < INF) {
                    cap[idx + 2][qIdx + 2 + N*N] = INF;
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> N >> T;
    memset(distMatrix, 0x3f, sizeof(distMatrix));
    for (int i = 0; i < N; ++i) cin >> gridA[i];
    for (int i = 0; i < N; ++i) cin >> gridB[i];
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (gridA[i][j] == 'Z') {
                zombieRow = i;
                zombieCol = j;
            }
        }
    }
    bfs(zombieRow, zombieCol, distMatrix[zombieRow*N + zombieCol], false);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                bfs(i, j, distMatrix[i*N + j], true);
            }
        }
    }
    constructGraph();
    cout << edmondsKarp(2 + N*N + N*N, 0, 1) << '\n';
}
